  ON CONFLICT (id) DO UPDATE SET mod = excluded.mod, category = excluded.category, title = excluded.title, pitch = excluded.pitch, experience = excluded.experience, how = excluded.how, risks = excluded.risks, audience = excluded.audience, in_world = excluded.in_world, tos_safe = excluded.tos_safe, top_pick = excluded.top_pick, wow = excluded.wow, feasibility = excluded.feasibility, effort = excluded.effort, sort_order = excluded.sort_order, added_version = excluded.added_version, retired = excluded.retired;
