INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('watch-quiet-hours', 'ackerman-watch', 'T-Watch S3 Plus · Power and nearby play', 'Quiet hours that respect sleep', 'Keep the wrist calm at night without losing the conversation.', 'The watch stays dim and silent during family-set hours; the next glance shows waiting replies.', 'Store a small schedule locally, gate notifications and keep durable history on the service.', 'Clock drift and emergency controls need a clear override.', 'Families setting bedtime routines', 1, 1, 0, 8, 'medium', 'medium', 7, 2, 0)
