INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('watch-trail-glance', 'ackerman-watch', 'T-Watch S3 Plus · Power and nearby play', 'Scout Trail in one glance', 'Let a tiny game turn fit the round trip to the wrist.', 'Two large choices appear, then the story waits until the child asks for another turn.', 'Keep Scout Trail logic in shared Lua and render only the current choice on the watch canvas.', 'Touch size and battery draw need a worn-device acceptance test.', 'Kids playing between activities', 1, 1, 0, 8, 'high', 'medium', 8, 2, 0)
