INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ackerman-offline-outbox', 'ackerman', 'Ackerman OS · Trust and continuity', 'Encrypted offline outbox', 'Write now; send once a trusted connection returns.', 'A watch or Deck holds a reply through a tunnel or dead zone and sends it once, with the same turn ID.', 'Encrypt per-device pending turns, preserve idempotency and reconcile accepted receipts on reconnect.', 'Replay protection, storage wear and a lost-key recovery path need hardware tests.', 'Families moving between Wi-Fi and radio', 1, 1, 1, 9, 'medium', 'large', 0, 1, 0)
  ON CONFLICT (id) DO UPDATE SET mod = excluded.mod, category = excluded.category, title = excluded.title, pitch = excluded.pitch, experience = excluded.experience, how = excluded.how, risks = excluded.risks, audience = excluded.audience, in_world = excluded.in_world, tos_safe = excluded.tos_safe, top_pick = excluded.top_pick, wow = excluded.wow, feasibility = excluded.feasibility, effort = excluded.effort, sort_order = excluded.sort_order, added_version = excluded.added_version, retired = excluded.retired;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ackerman-family-controls', 'ackerman', 'Ackerman OS · Trust and continuity', 'Family permissions that are visible', 'Give a parent clear control over device enrollment and access.', 'The parent can see which devices may join the family thread and revoke one without re-enrolling everything.', 'Add scoped device grants, revocation receipts and a read-only family dashboard.', 'Do not expose a parent credential to the child device or public site.', 'Parents managing watches, decks and tablets', 0, 1, 1, 8, 'medium', 'large', 1, 1, 0)
  ON CONFLICT (id) DO UPDATE SET mod = excluded.mod, category = excluded.category, title = excluded.title, pitch = excluded.pitch, experience = excluded.experience, how = excluded.how, risks = excluded.risks, audience = excluded.audience, in_world = excluded.in_world, tos_safe = excluded.tos_safe, top_pick = excluded.top_pick, wow = excluded.wow, feasibility = excluded.feasibility, effort = excluded.effort, sort_order = excluded.sort_order, added_version = excluded.added_version, retired = excluded.retired;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ackerman-honest-status', 'ackerman', 'Ackerman OS · Trust and continuity', 'What works, shown honestly', 'Show sync, voice and radio state on every screen.', 'A message says waiting, sent, answered or needs attention; there is no mystery spinner.', 'Share a small state machine in Nelua and render it for each canvas.', 'A network timeout can leave an accepted turn; status must reconcile rather than duplicate it.', 'Everyone using the shared thread', 1, 1, 0, 8, 'high', 'medium', 2, 1, 0)
  ON CONFLICT (id) DO UPDATE SET mod = excluded.mod, category = excluded.category, title = excluded.title, pitch = excluded.pitch, experience = excluded.experience, how = excluded.how, risks = excluded.risks, audience = excluded.audience, in_world = excluded.in_world, tos_safe = excluded.tos_safe, top_pick = excluded.top_pick, wow = excluded.wow, feasibility = excluded.feasibility, effort = excluded.effort, sort_order = excluded.sort_order, added_version = excluded.added_version, retired = excluded.retired;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ackerman-home-voice-receipts', 'ackerman', 'Ackerman OS · Trust and continuity', 'One reply, one voice, three screens', 'Keep Levi’s home voice and text tied to the same turn across watch, Deck and tablet.', 'A child hears the reply on the tablet and sees the exact same answer on a wrist or field Deck.', 'Carry immutable turn and clip IDs through the durable Cloudflare history and let each device choose its own display or playback.', 'Audio availability, expiry and resumed playback need honest status; no device should claim a clip it has not downloaded.', 'Families using all three companions', 1, 1, 0, 10, 'medium', 'large', 3, 2, 0)
  ON CONFLICT (id) DO UPDATE SET mod = excluded.mod, category = excluded.category, title = excluded.title, pitch = excluded.pitch, experience = excluded.experience, how = excluded.how, risks = excluded.risks, audience = excluded.audience, in_world = excluded.in_world, tos_safe = excluded.tos_safe, top_pick = excluded.top_pick, wow = excluded.wow, feasibility = excluded.feasibility, effort = excluded.effort, sort_order = excluded.sort_order, added_version = excluded.added_version, retired = excluded.retired;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ackerman-family-device-map', 'ackerman', 'Ackerman OS · Trust and continuity', 'A family map of trusted devices', 'See which watch, Deck and tablet belong to the conversation.', 'A parent can name each device, see its last successful sync and retire a missing one.', 'Use device-scoped credentials and revocation receipts without copying the parent token onto a child device.', 'A lost device must lose access promptly while previously queued turns reconcile safely.', 'Parents provisioning Ackerman devices', 0, 1, 0, 9, 'medium', 'large', 4, 2, 0)
  ON CONFLICT (id) DO UPDATE SET mod = excluded.mod, category = excluded.category, title = excluded.title, pitch = excluded.pitch, experience = excluded.experience, how = excluded.how, risks = excluded.risks, audience = excluded.audience, in_world = excluded.in_world, tos_safe = excluded.tos_safe, top_pick = excluded.top_pick, wow = excluded.wow, feasibility = excluded.feasibility, effort = excluded.effort, sort_order = excluded.sort_order, added_version = excluded.added_version, retired = excluded.retired;
INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ackerman-app-kit', 'ackerman', 'Ackerman OS · Portable play', 'Portable Lua app kit', 'Make one safe app run on watch, Deck and Android.', 'A small game can use buttons, notes and a bounded canvas without three rewrites.', 'Publish versioned app capabilities, a simulator and packaging checks around the shared Lua runtime.', 'Memory, display shape and permissions differ across devices.', 'Makers building family apps and games', 1, 1, 0, 9, 'medium', 'large', 5, 1, 0)
