INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ackerman-cross-device-resume', 'ackerman', 'Ackerman OS · Portable play', 'Continue a game on another device', 'Carry an optional game checkpoint between companions.', 'Start a trail on the watch and finish its next choice on the tablet.', 'Sync explicit versioned app checkpoints through the family service with per-app consent.', 'Offline conflicts and private note data need strict separation.', 'Families who switch between devices', 0, 1, 0, 7, 'medium', 'large', 6, 1, 0)
