INSERT INTO ideas (id, mod, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ackerman-game-saves', 'ackerman', 'Ackerman OS · Portable play', 'Save a tiny adventure across companions', 'Let a Scout Trail checkpoint travel with its owner.', 'The next choice is waiting on the tablet after playing on the watch, with a clear conflict prompt if both moved offline.', 'Version shared Lua app state and sync only opt-in game checkpoints through the family service.', 'Never sync private Field Notes by accident; offline conflicts need a visible resolution.', 'Kids switching between watch, Deck and tablet', 1, 1, 0, 10, 'medium', 'large', 7, 2, 0)
